INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Auf Wiedersehen Monty', 'Monty On the Run is a platform-style game featuring Monty Mole, a coal thief fleeing across Europe to escape the Intermole agency. Players navigate Monty through 80 screens representing European landmarks, using various movement techniques like super-leaps and ceiling suspension. The goal is to collect Eurocheques and plane tickets while avoiding hazards. The game incorporates unique elements such as drunkenness effects from wine bottles and aerial combat sequences. As the third main entry in the Monty Mole series, it builds upon the gameplay mechanics of its predecessors while introducing new challenges and environments.' FROM games WHERE igdb_id = 13350 ON CONFLICT (game_id, language_code) DO NOTHING;
