INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penguin Land', 'Penguin Land, known as Doki Doki Penguin Land Uchū Daibōken (どきどきペンギンランド宇宙大冒険? lit. "Thump Thump Penguin Land: Great Outer Space Adventure") in Japan, is a Sega Master System game and the second game in the Doki Doki Penguin Land series. In this game you play as a penguin going through a puzzle platformer stage and try to guide your egg around the polar bears, rocks and other hazards to the end of the stage. The game has a total of 50 stages and a level editor which can save up to 15 additional levels. The level editor data is stored on the game''s battery back-up RAM.' FROM games WHERE igdb_id = 49152 ON CONFLICT (game_id, language_code) DO NOTHING;
