INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizards & Warriors', 'You are Kuros, a powerful knight who enter the woods of Elrond. Legend says that a powerful wizard named Malkil has has gone completely mad during his years and turned his powerful magic to the dark side. Malkil has his base on the castle IronSpire where he has imprisoned a young and beautiful princess. It is up to Kuros to save the princess once and for all.' FROM games WHERE igdb_id = 9720 ON CONFLICT (game_id, language_code) DO NOTHING;
