INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Fighter', 'Street Fighter is the first fighting game produced by Capcom and the very first game in the Street Fighter series. While it did not achieve the same popularity as its sequels when it was first released, the original Street Fighter introduced some of the conventions made standard in later games such as attack buttons and special command-based techniques.' FROM games WHERE igdb_id = 6930 ON CONFLICT (game_id, language_code) DO NOTHING;
