INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'After Burner II', 'After Burner II is an arcade-style flight game released by Sega in 1987. It is the second game in the After Burner series. In the game, players fly a F-14 Tomcat jet fighter, gunning down enemies while avoiding incoming fire. Like OutRun, another Sega arcade game, After Burner II came in several versions, the most famous being a large, servo actuated, sit-down cabinet which resembled a cockpit and moved according to the motion of the plane onscreen. The cockpit would bank in the same direction the on-screen aircraft was banking. There was also a more basic upright cabinet version.' FROM games WHERE igdb_id = 5352 ON CONFLICT (game_id, language_code) DO NOTHING;
