INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Gun', 'Top Gun was released in 1987 for the PC, Commodore 64, ZX Spectrum and Nintendo Entertainment System (NES) (with an equivalent version for Nintendo Vs. Series arcade cabinets). The Commodore and Spectrum versions were developed by Ocean while Thunder Mountain handled the PC version of the game. Konami developed the Nintendo version. The NES version was released on November 1987 in North America, December 11, 1987 in Japan and on November 30, 1988 in Europe and Australia. According to Game Over by David Sheff, the NES version sold over 2 million copies.
