INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jaws', 'Jaw is an action-adventure game based on the popular movie franchise. Players control a diver and a boat, navigating between ports, collecting shells as currency and battling sea creatures including the infamous great white shark Jaws. With simple mechanics and a mix of underwater combat and overworld sailing, the game offers a fast-paced arcade-style experience loosely inspired by the films.' FROM games WHERE igdb_id = 68385 ON CONFLICT (game_id, language_code) DO NOTHING;
