INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exolon', 'Exolon is a classic side-scrolling action game developed by Hewson Consultants and released in 1987 for various 8-bit home computer platforms. Players control Vitorc, a space marine equipped with an armored exoskeleton suit, as he navigates through 125 screens of hostile alien terrain. The game''s core gameplay revolves around precise shooting, strategic grenade use, and skillful maneuvering to overcome a relentless array of enemies and environmental hazards. Known for its high difficulty level, Exolon challenges players with fast-paced action that demands quick reflexes and careful planning.
