INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3-D WorldRunner', 'The battle of a lifetime comes alive in 3-D! The wildest of the space cowboys is out looking for adventure. Now he''s got it and he needs your help. A strange world terrorized by Grax, the Alien Serpentbeast, has asked you, Worldrunner, for help. Knowing you can outrun, outjump and outblast anyone or anything, you race into battle. But this is no ordinary fight. These battles will carry you to eight strange planets filled with bottomless pits, shooting stars, and poisonous aliens, all sworn to defend their Serpent King. And each new world is ruled by an Alien Serpentbeast more terrifying and more powerful than anything you''ve ever seen before. Are you ready, Worldrunner? They''re waiting for you!' FROM games WHERE igdb_id = 48030 ON CONFLICT (game_id, language_code) DO NOTHING;
