INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sky Shark', 'Sky Shark (released in Japan as "Hi Sho Zame", and in Europe as "Flying Shark")is a military-themed vertically scrolling shoot ''em up game in which players take control of the titular biplane through five increasingly difficult levels in order to defeat an assortment of military enemy forces like tanks, battleships, airplanes and artillery as the main objective. The title initially appears to be very standard, as players control their plane over a constantly scrolling background and the scenery never stops moving until a runway is reached. Players have only two weapons at their disposal: the standard shot that travels a max distance of the screen''s height and three bombs.
