INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zelda II: The Adventure of Link', 'Zelda II: The Adventure of Link is the second major installment in The Legend of Zelda series and the direct sequel to the first game. Like its predecessor, it features dungeons that must be located in the overworld and searched for an item that will prove useful. However, the game presents many very important gameplay changes compared to the previous one, affecting especially the movements and the combat. Moving around the world map involves encounters with enemies that take place on a side-scrolling playfield rather than the top-down perspective for which the series became known.' FROM games WHERE igdb_id = 1025 ON CONFLICT (game_id, language_code) DO NOTHING;
