INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mickey Mousecapade', '"Help! Help!" echos a mysterious voice. Mickey Mouse, the famous world explorer, has heard the cries of one of his friends and he''s off on a rescue mission... This adventure starts in a zany Fun House. Join Mickey and Minnie as they turn it inside out looking for their missing friend. A mischievous creature may fly off with Minnie, and you''ll have to get her back. Now that Minnie is safe, you must help our heroes make it across a vast ocean - on foot! Even the feisty flying fish can''t stop Mickey from his search, but what about the cantankerous crocodile waiting at the shore? Enter the world of fantasy, mystery and excitement with Mickey and Minnie as you solve the mystery of Mickey''s missing friend!' FROM games WHERE igdb_id = 8126 ON CONFLICT (game_id, language_code) DO NOTHING;
