INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zillion II: The Tri Formation', 'They''re at it again. The dreaded Norsa Empire is back... and stronger than ever before. This time they won''t make any mistakes. Others have tried to stop them and all have failed. The evil Baron Ricks knows you are coming. And it''s a trap! But you''re the galaxy''s last hope. Can you do what''s never been done before?' FROM games WHERE igdb_id = 46114 ON CONFLICT (game_id, language_code) DO NOTHING;
