INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alien-syndrome--1', 4478, '1987-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co85m5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fc0duspqfahaxx3xtnmi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Syndrome', 'The time bomb is set. It''s the only sure way to get rid of these aliens. For good. They''re vile. Vicious. And villainous. And they''ve infested our outcolony. They''re holding hundreds of inhabitants hostage. Some of them your friends. So get in there. And get blasting. Inside, you''ll find state-of-the-art weaponry. It''s yours for the taking. There''s sector after sector to purge. Each more intricate than the one before it. And there are Super Aliens to confront. Each more hideous than the one before it. Get the hostages out. And get as many aliens as you can. Before the blast gets all of you.' FROM games WHERE igdb_id = 4478 ON CONFLICT (game_id, language_code) DO NOTHING;
