INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainbow Islands: The Story of Bubble Bobble 2', 'Rainbow Islands is a 1987 arcade game developed and published by Taito. The arcade version was licensed to Romstar for North American manufacturing and distribution. The game is subtitled "The Story of Bubble Bobble 2" and is the sequel to Taito''s hit game Bubble Bobble from the previous year. It is the second of four arcade games in the Bubble Bobble series. The game was ported for numerous home computers and game consoles.' FROM games WHERE igdb_id = 4405 ON CONFLICT (game_id, language_code) DO NOTHING;
