INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RoadBlasters', 'The objective of the game is to complete all 50 rallies without running out of fuel. There is no limit to how many vehicles a player can receive to complete a rally, as long as they have fuel. However, the destruction of the vehicle will subtract a small amount from the player''s fuel tank. In the arcade, Genesis and Lynx versions, players could start the game at a higher rally, with additional opportunities to jump several levels from time to time. Players can continue their game from where they left off; however, the player has only one chance to complete the 50th and final rally. For completing the final rally the player gets one million points as a bonus. Players can get fuel in four ways: green globes, red globes, a checkpoint, and the rally point.' FROM games WHERE igdb_id = 12367 ON CONFLICT (game_id, language_code) DO NOTHING;
