INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2400 A.D.', '2400 A.D. is a futuristic RPG game. The game was developed by Origin systems and is based on Ultima 4 engine. The story takes place in the city called Metropolis. The city has been conquered by an alien race known as Tzorg. You have to find the underground resistance and join the battle against the Tzorg.' FROM games WHERE igdb_id = 2412 ON CONFLICT (game_id, language_code) DO NOTHING;
