INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Police Quest: In Pursuit of the Death Angel', 'Police Quest: In Pursuit of The Death Angel is an adventure game in which gameplay is centered on interacting with the environment to resolve a series of scenarios. These largely revolve around typical police work, such as securing crime scenes and recovering stolen vehicles, while following proper duty procedures. The original release of the game required the player to type in the desired actions, such as opening doors, pressing buttons, or firing one''s gun, while the remake allows the player to use the mouse to select actions from a menu and objects in the environment.' FROM games WHERE igdb_id = 1924 ON CONFLICT (game_id, language_code) DO NOTHING;
