INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Karnov', 'Karnov is a 1987 platform arcade game. It is the debut of Data East''s mascot of the same name. After Data East became defunct due to bankruptcy in 2003, Paon, a company comprising former Data East staff, acquired the rights to Karnov, along with multiple other Data East games.
