INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zeliard', 'Zeliard is a side-scrolling action game with platforming and role-playing elements. The game world is divided into hostile labyrinths, which occupy its largest portion and contain maze-like passages for Duke Garland to traverse, as well as enemies that must be dealt with. Crests and keys must often be collected in order to ensure the progress to the next area. Garland takes damage from enemy attacks as well as the environment (hidden spikes, high temperature, etc.), but suffers no damage should he fall off a platform.
