INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maniac Mansion', 'Maniac Mansion is a 1987 graphic adventure video game developed and published by Lucasfilm Games. It follows teenage protagonist Dave Miller as he attempts to rescue his girlfriend from a mad scientist, whose mind has been enslaved by a sentient meteor. The player uses a point-and-click interface to guide Dave and two of his six playable friends through the scientist''s mansion while solving puzzles and avoiding dangers. Gameplay is nonlinear, and the game must be completed in different ways based on the player''s choice of characters. Initially released for the Commodore 64 and Apple II, Maniac Mansion was Lucasfilm Games'' first self-published product.' FROM games WHERE igdb_id = 192 ON CONFLICT (game_id, language_code) DO NOTHING;
