INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Quest II: Vohaul''s Revenge', 'Just when you thought it was safe to go back into space, He''s Back! And he wants revenge! Sludge Vohaul, the demented evil scientist (whose sinister plan you unknowingly foiled in our last episode), is seething over his Sarien slip-up. Madder than a drenched Astrochicken, (and still determined to rule the galaxy) Vohaul has devised a new plan. A nasty plan. A plan so evil that only one as wickedly sadistic as he could imagine it. Yes, the worst nightmare ever is about to come knocking on your door- and it won''t take No for an answer!
