INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'APB', 'APB ("All Points Bulletin") is a 1987 arcade game where the player assumes the role of "Officer Bob," a rookie police officer. As Bob, players drive around the city, ticketing motorists for minor infractions and pulling over more serious offenders. Eventually, players must apprehend criminals for which an all-points bulletin has been called.' FROM games WHERE igdb_id = 11905 ON CONFLICT (game_id, language_code) DO NOTHING;
