INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RoboWarrior', 'Robowarrior takes place on an alien planet called Altile. The player operates a cyborg named ZED (Z-type Earth Defence). In the game, ZED raids Altile to fight the Xantho empire and destroy its leader, Xur. ZED deploys bombs to clear a path through rocks, walls, and forests, while killing enemies and collecting items.' FROM games WHERE igdb_id = 8473 ON CONFLICT (game_id, language_code) DO NOTHING;
