INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('airball', 2302, '1987-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8d4h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qa4qhk1dsss6cjbbuaja.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airball', '"Now you''re really in trouble" said the evil Wizard. "I''m turning you into a ball of air and sending you into my mansion, with over 250 rooms, to search for the Spellbook that may give you the clues on how to transform yourself into a human again. It''s not as easy as it sounds, for you, as the ball of air, have a slow leak, and you''ll need to jump on an air pump in some rooms to remain inflated. Take heed, for if you pump up too much you will burst! If you are lucky enough to find the book in these rooms, you''ll next have to pick up the objects I''ve left, such as: crosses, tins of beans, a Buddha, a dragon statue, a pumpkin, a flask, and even crates that you''ll need to get over treacherous obstacles! This is your one chance for survival," he cackles.
