INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'La Abadía del Crimen', 'La abadía del crimen (The Abbey of Crime) is a computer video game programmed in 1987 by Paco Menéndez and Juan Delcán. The game was originally conceived as a version of Umberto Eco''s book The Name of the Rose. However, the developers received no reply from Eco in order to secure the rights for the name, so the game was released as La abadía del crimen.
