INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aztec Adventure', 'Gameplay involves the player trying to reach Paradise by exploring ten different lands, including desert, marshes, ruins, underground waterways, and forest. While exploring you can collect weapons, by destroying plants. A variety of in-game weapons can be found, some more powerful than others. Some weapons can be used against bosses, which can take a certain amount of hits from the player''s default weapon, unless he has companions. The player''s companions need to be hired with gold, and until he pays them they remain your enemies. Players must either bribe them or battle them to make them join his quest.' FROM games WHERE igdb_id = 45668 ON CONFLICT (game_id, language_code) DO NOTHING;
