INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy', 'Final Fantasy, also known as FFI in re-releases, is the first role-playing game title in Square''s flagship Final Fantasy series. The game puts players in control of four characters known as the Warriors of Light, and begins by asking the player to select the classes and names of each. The Warriors of Light can traverse the maps of dungeons and towns, which are connected by a world map, and will run into random encounters with enemies or fight bosses.' FROM games WHERE igdb_id = 385 ON CONFLICT (game_id, language_code) DO NOTHING;
