INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Magic of Scheherazade', 'Magic of Scheherazade is a mixture of action- and turn-based combat RPG styles. Wandering through Arabia, you''ll encounter enemies whom you''ll fight in real time, using various weapons. You''ll also be attacked by enemies with whom you''ll engage in strategic, party-vs.-party combat. You can choose from three character classes: Fighter, Saint, and Magician. Each class has its own special abilities that you''ll use in battles as well as during your exploration of the game world.' FROM games WHERE igdb_id = 48078 ON CONFLICT (game_id, language_code) DO NOTHING;
