INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xenophobe', 'Xenophobe is a 1987 arcade game and the goal of each level is to defeat all the aliens before time runs out. Levels may contain more than one floor, and players use elevators or holes to move between floors to defeat all of the aliens. Players can also pick up more powerful weapons and other items to help in their eradication of the aliens.' FROM games WHERE igdb_id = 12245 ON CONFLICT (game_id, language_code) DO NOTHING;
