INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skate or Die', '"Skate or Die!" is a skateboarding game that was first released by Electronic Arts in 1987 for the Commodore 64. As EA''s first internally developed title, it was created to capitalize on the success of the Epyx sports games, with inspiration for the game''s concept coming from the Atari arcade game "720°". The game allows up to eight players to compete in a series of five different skateboarding events: freestyle ramp, high jump, a downhill race, a downhill jam, and a pool joust. Each event has its own unique challenges and objectives.
