INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Missile Defense 3-D', 'War has been declared between two super powers. At play are real nuclear missiles and the outcome looks dim. If their missiles make contact, there''s no chance for survival. Luckily there''s hope. You and The Eliminator, the only anti-nuclear laser in operation. Aboard a fugitive space station, you''re armed for intervention and your mission is clear: stop all nuclear missiles. But it won''t be easy. Because those missiles are being launched at you, too. So play for keeps. This is the most important challenge you may ever face.' FROM games WHERE igdb_id = 45672 ON CONFLICT (game_id, language_code) DO NOTHING;
