INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaga ''88', 'The gameplay in Galaga ''88 is built on the same premise as that of the original Galaga game, but is in many ways more complex and more difficult. The game is divided into a series of 29 Stages distributed through eight Worlds. The starship Galaga accelerates between Stages and Worlds and even to higher dimensions (go to the section on Dimensional Travel below to find out more).
