INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Zone: The Maze', 'The evil Menons have returned... in multi-level bases which are hidden in seven different planets! The brave Opa-Opa has been called to battle their evil threat. And joining him in the fight is his younger brother, Upa-Upa. Your Mission: Guide this brave team of brothers through level after level of treacherous mazes. Get the golden coins stolen by the Menon hoard and use them to purchase powerful weapons. The Fantasy Zone is counting on you! Don''t let them down.' FROM games WHERE igdb_id = 45658 ON CONFLICT (game_id, language_code) DO NOTHING;
