INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Faery Tale Adventure', 'You take on the role of three brothers wandering through the magical land of Holm. Real-time interaction reminiscent of Ultima 7. An extremely large world, touted at the time as the largest game world ever created, about 17,000 computer screens worth of terrain. The game was first developed for Amiga and after achieving a huge success, the game was ported to more platforms including PC.' FROM games WHERE igdb_id = 12087 ON CONFLICT (game_id, language_code) DO NOTHING;
