INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Feud', 'Feud is a top-down action-adventure game where you step into the shoes of one of two rival wizards, Learic or Leanoric. Navigate a sprawling, maze-like world filled with dangers, secrets, and the ingredients needed to craft powerful spells. Your mission is to outwit and overpower your opponent by gathering these ingredients and using them to create spells that can turn the tide in your favor.' FROM games WHERE igdb_id = 12094 ON CONFLICT (game_id, language_code) DO NOTHING;
