INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Goonies II', 'The Goonies II features two modes of play: platform and first-person. Most of the game is played as the former as the player works through a non-linear map. The player moves Mikey to new areas of the map by ladders or doors that may act as warp zones. Several different types of zones are found in the game, each with distinct enemies, graphics and music.' FROM games WHERE igdb_id = 18916 ON CONFLICT (game_id, language_code) DO NOTHING;
