INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Apocalypse', 'It is the sequel to Crazy Comets. The game involves repetitively shooting planets and moons as they grow in size and threaten to collide with the player''s space ship. The game is noted for its Rob Hubbard music, fast paced action and 2 player co-op game play.' FROM games WHERE igdb_id = 22525 ON CONFLICT (game_id, language_code) DO NOTHING;
