INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blasteroids', 'The Player controls a spaceship viewed from "above" in a 2D representation of space, by rotating the ship, and using thrust to give the ship momentum. To slow down or completely stop moving, the player has to rotate the ship to face the direction it came from, and generate the right amount of thrust to nullify its momentum. The ship has a limited amount of fuel to generate thrust with. This fuel comes in the form of "Energy" that is also used for the ship''s Shields which protect it against collisions and enemy fire. Once all Energy is gone, the player''s ship is destroyed. The ship can shoot to destroy asteroids and enemy ships. The ship can also be transformed at will into 3 different versions, namely the "Speeder", the fastest version, the "Fighter", which has the most firepower, and the "Warrior", which has extra armour.' FROM games WHERE igdb_id = 11967 ON CONFLICT (game_id, language_code) DO NOTHING;
