INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocky', 'Rocky Super Action Boxing is the first licensed video game based on the popular Rocky film series. The game is based on Rocky III and was designed by Coleco. In the game, the player can play as either Rocky Balboa or Clubber Lang in the game, either against the computer in a one player game, or against each other in a "Head to Head" two player mode. There is also a "Demo" mode if the player wants to watch Rocky and Clubber Lang fight.
