INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mike Tyson''s Punch-Out!!', 'Punch-Out!!, originally released in North America as Mike Tyson''s Punch-Out!!, is a boxing sports fighting video game for the Nintendo Entertainment System (NES) developed and published by Nintendo in 1987. Part of the Punch-Out!! series, it is a port of both the Punch-Out!! and Super Punch-Out!! arcade games (particularly the latter) with some variations.
