INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/zrssin8lw2mhvv8ybig7.jpg', 0, true FROM games WHERE igdb_id = 2906 ON CONFLICT DO NOTHING;
INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/sciisr.jpg', 1, false FROM games WHERE igdb_id = 2906 ON CONFLICT DO NOTHING;
INSERT INTO game_screenshots (game_id, url, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/sciisq.jpg', 2, false FROM games WHERE igdb_id = 2906 ON CONFLICT DO NOTHING;
INSERT INTO game_videos (game_id, url, thumbnail_url, title, video_type, display_order, is_featured) SELECT id, 'https://www.youtube.com/watch?v=XqXpWJhsuaI', 'https://img.youtube.com/vi/XqXpWJhsuaI/maxresdefault.jpg', 'Trailer', 'trailer', 0, true FROM games WHERE igdb_id = 2906 ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 2906 AND rs.code = 'USK' AND r.code = '16' ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 2906 AND rs.code = 'PEGI' AND r.code = '16' ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 2906 AND rs.code = 'ESRB' AND r.code = 'M' ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'en', 'English', true, true, true FROM games WHERE igdb_id = 2906 ON CONFLICT DO NOTHING;
